<?php $pageTitle='Members';require __DIR__.'/_top.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare("UPDATE users SET status=? WHERE id=?")->execute([$_POST['status']==='active'?'active':'blocked',(int)$_POST['id']]);flash('Member status updated.');header('Location: '.url('admin/users.php'));exit;}$rows=$pdo->query("SELECT * FROM users ORDER BY created_at DESC")->fetchAll();$f=get_flash(); ?>
<?php if($f): ?><p class="notice"><?= e($f[0]) ?></p><?php endif; ?><section class="panel"><div class="panel-heading"><div><span class="eyebrow">COMMUNITY</span><h2>Registered growers and buyers</h2></div><span class="status"><?= count($rows) ?> members</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Phone</th><th>Role</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $u): ?><tr><td><b><?= e($u['name']) ?></b><small class="subline"><?= e($u['email']) ?></small></td><td><?= e($u['phone']) ?></td><td><?= e(ucfirst($u['role'])) ?></td><td><?= e($u['status']) ?></td><td><?= e(date('d M Y',strtotime($u['created_at']))) ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="status" value="<?= $u['status']==='active'?'blocked':'active' ?>"><button class="btn btn-small"><?= $u['status']==='active'?'Block':'Activate' ?></button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6">No members registered yet.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/_bottom.php'; ?>
